def get_square_free_part(n):
    """Get the square-free part of n"""
    result = 1
    d = 2
    while d * d <= n:
        count = 0
        while n % d == 0:
            n //= d
            count += 1
        if count % 2 == 1:
            result *= d
        d += 1
    if n > 1:
        result *= n
    return result

def maxSum(nums):
    n = len(nums)
    # Dictionary to store sum for each square-free part
