        square_free = get_square_free_part(i)
        if square_free not in group_sums:
            group_sums[square_free] = 0
        group_sums[square_free] += nums[i - 1]  # Convert to 0-indexed for nums

    return max(group_sums.values()) if group_sums else 0

def reachingPoints(sx, sy, tx, ty):
    while tx > 0 and ty > 0:
        if tx == ty:
            return tx == sx and ty == sy
        if tx > ty:
            if tx % ty == 0:
                return (tx // ty == sx and ty == sy) or (ty == sx and tx // ty == sy)
            tx = tx % ty
        else:
            if ty % tx == 0:
                return (ty // tx == sx and tx == sy) or (tx == sx and ty // tx == sy)
            ty = ty % tx

    return tx == sx and ty == sy

