def countDigitOne(n):
    if n <= 0:
        return 0

    digits = []
    temp = n
    while temp > 0:
        digits.append(temp % 10)
        temp //= 10
    digits.reverse()

    res = 0
    count_1 = 0

    for i in range(len(digits) - 1):
        if digits[i] == 1:
            res += count_1 + 1
            count_1 += 1
        elif digits[i] > 1:
            res += count_1 + 1
            count_1 += 1
        else:
            count_1 += 1

    # Handle the last digit
    if digits[-1] >= 1:
        res += 1

    return res

def countAnagrams(s):
    MOD = 10**9 + 7

    def factorial(n):
        if n <= 1:
            return 1
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % MOD
        return result

    words = s.split()
    ways = 1

    for word in words:
        n = len(word)
        fact = factorial(n)

        # Count frequency of each character
        freq = {}
        for char in word:
            freq[char] = freq.get(char, 0) + 1

        # For each frequency, divide fact by factorial(frequency)
        for count in freq.values():
            fact = (fact * pow(factorial(count), MOD - 2, MOD)) % MOD

        ways = (ways * fact) % MOD

    return ways

def consecutiveNumbersSum(n):
    count = 0
    for k in range(1, n):
        x = n / (k + 1) - k / 2
        if x <= 0:
            break
        if x == int(x):  # x is an integer
            count += 1
    return count + 1

def xorGame(nums):
    xor = 0
    for num in nums:
        xor ^= num

    return len(nums) % 2 == 0 or xor == 0

def poss(groups):
    # Initialize sub with usageLimits[0]
    sub = [usageLimits[0]]

    # For i in range(1, n): append usageLimits[i] - usageLimits[i-1] to sub
    for i in range(1, len(usageLimits)):
        sub.append(usageLimits[i] - usageLimits[i-1])

    # For i in range(groups, 0, -1): decrement sub[i] by 1
    for i in range(groups, 0, -1):
        if i >= len(sub):
            return False
        sub[i-1] -= 1

    # Check if any sub[i] < 0
    for i in range(len(sub)):
        if sub[i] < 0:
            return False

    return True

# Binary search for maximum groups
left, right = 1, len(usageLimits)
result = 1

while left <= right:
    mid = (left + right) // 2
    if poss(mid):
        result = mid
        left = mid + 1
    else:
        right = mid - 1

return result
